/bin/bash -lc "perl -0777 -ne '
  my @records = split(/"'^>/m);
  shift @records;
  for my $rec (@records) {
    my @lines = split(/'"\\n/, "'$rec);
    my $header = shift @lines;
    my $seq = uc(join("", @lines));
    my ($id) = split(/'"\\s+/, "'$header);
    for my $q ("CACACACAGGAGAT") {
      my $p = 0;
      while (($p = index($seq, $q, $p)) >= 0) {
        print "$id'"\\t"'$p-" . ($p + length($q) - 1) . "'"\\t+\\n\";
        "'$p++;
      }
    }
    my $q = "CACACACAGGAGAT";
    my $rc = reverse($q);
    $rc =~ tr/ACGT/TGCA/;
    my $p = 0;
    while (($p = index($seq, $rc, $p)) >= 0) {
      print "$id'"\\t"'$p-" . ($p + length($rc) - 1) . "'"\\t-\\n\";
      "'$p++;
    }
  }
'"' GCF_000001215.4_Release_6_plus_ISO1_MT_genomic.fna"

/bin/bash -lc "perl -0777 -ne '
  my @r = split(/"'^>/m); shift @r;
  for my $x (@r) {
    my @l=split(/'"\\n/,"'$x); my $h=shift @l; my $s=uc join("",@l); my ($id)=split(/'"\\s+/,"'$h);
    next unless $id eq "NT_033779.5";
    my $p=index($s,"CACACACAGGAGAT");
    print "$h'"\\nposition="'$p'"\\ncontext=\" . substr("'$s,$p-20,54) . "'"\\n\";
  }
' GCF_000001215.4_Release_6_plus_ISO1_MT_genomic.fna"
